import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(aLine[i]);
        }
        int half = n / 2;

        List<Long> leftPart = new ArrayList<>();
        List<Long> rightPart = new ArrayList<>();

        computeSumsLeft(a, 0, 0, half, m, leftPart);
        computeSumsRight(a, half, 0, n, m, rightPart);

        long maxTotal = 0;

        Set<Long> leftSet = new HashSet<>(leftPart);
        List<Long> sortedLeft = new ArrayList<>(leftSet);
        Collections.sort(sortedLeft);

        for (Long val : rightPart) {
            int position = Collections.binarySearch(sortedLeft, m - val);
            if (position < 0) {
                position = -position - 1;
            }
            if (position > 0) {
                long candidateSum = sortedLeft.get(position - 1) + val;
                if (candidateSum > maxTotal) {
                    maxTotal = candidateSum;
                }
            }
        }
        System.out.println(maxTotal);
    }

    private static void computeSumsLeft(long[] a, int index, long total, int limit, int m, List<Long> leftPart) {
        if (index == limit) {
            leftPart.add(total);
        } else {
            computeSumsLeft(a, index + 1, (total + a[index]) % m, limit, m, leftPart);
            computeSumsLeft(a, index + 1, total, limit, m, leftPart);
        }
    }

    private static void computeSumsRight(long[] a, int start, int index, int n, int m, List<Long> rightPart) {
        if (index == n) {
            rightPart.add(total);
        } else {
            computeSumsRight(a, start, index + 1, n, m, rightPart);
            computeSumsRight(a, start, index + 1, n, m, rightPart);
        }
    }
}
